    document.addEventListener("DOMContentLoaded", function () {
        var sidebar = document.getElementById("sidebar");
        var mainContent = document.getElementById("main-content");
        var sidebarOverlay = document.getElementById("sidebar-overlay");
        var menuBtn = document.getElementById("menuBtn");
        var themeToggle = document.getElementById("themeToggle");
        var chatInput = document.getElementById("chatInput");
        var sendBtn = document.getElementById("sendBtn");
        var chatHistory = document.getElementById("chat-history");
        var contextMenu = document.getElementById("context-menu");
        var htmlEl = document.documentElement;
        var isSidebarOpen = false;
        var touchStartX = 0;
        var touchCurrentX = 0;
        var longPressTimer;
        var themeMeta = document.querySelector('meta[name="theme-color"]');
        function toggleSidebar(open) {
            isSidebarOpen = open;
            if (open) {
                sidebar.classList.add("open");
                mainContent.classList.add("pushed");
                sidebarOverlay.classList.add("visible");
            } else {
                sidebar.classList.remove("open");
                mainContent.classList.remove("pushed");
                sidebarOverlay.classList.remove("visible");
            }
        }
        menuBtn.addEventListener("click", function () {
            toggleSidebar(!isSidebarOpen);
        });
        sidebarOverlay.addEventListener("click", function () {
            toggleSidebar(false);
        });
        document.addEventListener("touchstart", function (e) {
            touchStartX = e.touches[0].clientX;
        }, { passive: true });
        document.addEventListener("touchmove", function (e) {
            touchCurrentX = e.touches[0].clientX;
        }, { passive: true });
        document.addEventListener("touchend", function () {
            var diff = touchCurrentX - touchStartX;
            if (!isSidebarOpen && diff > 100 && touchStartX < 30) {
                toggleSidebar(true);
            } else if (isSidebarOpen && diff < -50) {
                toggleSidebar(false);
            }
            touchStartX = 0;
            touchCurrentX = 0;
        });
        themeToggle.addEventListener("change", function (e) {
            var isDark = e.target.checked;
            htmlEl.setAttribute("data-theme", isDark ? "dark" : "light");
            if (themeMeta) {
                themeMeta.setAttribute("content", isDark ? "#000000" : "#ffffff");
            }
        });
        if (window.matchMedia && window.matchMedia("(prefers-color-scheme: dark)").matches) {
            themeToggle.checked = true;
            htmlEl.setAttribute("data-theme", "dark");
            if (themeMeta) {
                themeMeta.setAttribute("content", "#000000");
            }
        }
        function addMessage(text, sender) {
            var group = document.createElement("div");
            group.className = "message-group " + sender;
            var bubble = document.createElement("div");
            bubble.className = "message-bubble typography-body";
            bubble.textContent = text;
            group.appendChild(bubble);
            chatHistory.appendChild(group);
            setTimeout(function () {
                chatHistory.scrollTo({ top: chatHistory.scrollHeight, behavior: "smooth" });
            }, 10);
        }
        async function sendMessage() {
            var text = chatInput.value.trim();
            if (!text) {
                return;
            }
            addMessage(text, "user");
            chatInput.value = "";
            chatInput.style.height = "auto";
            try {
                var response = await fetch("/api/chat", {
                    method: "POST",
                    headers: {
                        "Content-Type": "application/json"
                    },
                    body: JSON.stringify({ message: text })
                });
                if (!response.ok) {
                    throw new Error("Network response was not ok");
                }
                var data = await response.json();
                if (data && typeof data.reply === "string") {
                    addMessage(data.reply, "ai");
                }
            } catch (error) {
                console.error(error);
            }
        }
        sendBtn.addEventListener("click", function () {
            sendMessage();
        });
        chatInput.addEventListener("keydown", function (e) {
            if (e.key === "Enter" && !e.shiftKey) {
                e.preventDefault();
                sendMessage();
            }
        });
        chatInput.addEventListener("input", function () {
            this.style.height = "auto";
            this.style.height = this.scrollHeight + "px";
            if (this.value === "") {
                this.style.height = "auto";
            }
        });
        function handleContextMenu(e, target) {
            e.preventDefault();
            var clientX = e.clientX;
            var clientY = e.clientY;
            contextMenu.style.top = clientY + "px";
            contextMenu.style.left = clientX + "px";
            if (clientX + 200 > window.innerWidth) {
                contextMenu.style.left = window.innerWidth - 220 + "px";
            }
            contextMenu.classList.add("visible");
            function hideMenu() {
                contextMenu.classList.remove("visible");
                document.removeEventListener("click", hideMenu);
            }
            setTimeout(function () {
                document.addEventListener("click", hideMenu);
            }, 100);
        }
        chatHistory.addEventListener("contextmenu", function (e) {
            var bubble = e.target.closest(".message-bubble");
            if (bubble) {
                handleContextMenu(e, bubble);
            }
        });
        chatHistory.addEventListener("touchstart", function (e) {
            var bubble = e.target.closest(".message-bubble");
            if (bubble) {
                longPressTimer = setTimeout(function () {
                    var touch = e.touches[0];
                    handleContextMenu({ preventDefault: function () {}, clientX: touch.clientX, clientY: touch.clientY }, bubble);
                }, 500);
            }
        }, { passive: false });
        chatHistory.addEventListener("touchend", function () {
            clearTimeout(longPressTimer);
        });
        chatHistory.addEventListener("touchmove", function () {
            clearTimeout(longPressTimer);
        });
        var historyList = document.getElementById("history-list");
        var historyItems = ["[translate:UX Kutatás 2024]", "[translate:React Komponensek]", "[translate:Python Script]", "[translate:Design Rendszer]"];
        historyItems.forEach(function (item) {
            var div = document.createElement("div");
            div.className = "sidebar-item typography-body-reduced";
            div.innerHTML = '<i class="far fa-comment-alt"></i> ' + item;
            div.addEventListener("click", function () {
                toggleSidebar(false);
                document.getElementById("headerTitle").textContent = item;
            });
            historyList.appendChild(div);
        });
        var newChatBtn = document.getElementById("newChatBtn");
        newChatBtn.addEventListener("click", function () {
            document.getElementById("headerTitle").textContent = "[translate:Új beszélgetés]";
            chatHistory.innerHTML = "";
        });
    });
    </script>
